  `center_lng` decimal(11,8) DEFAULT NULL,
  `color` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#3B82F6' COMMENT 'Hex color for zone polygon on map',
  `opacity` decimal(3,2) NOT NULL DEFAULT '0.30' COMMENT 'Fill opacity 0.0-1.0',
  `delivery_fee` decimal(10,2) NOT NULL,
  `minimum_order` decimal(10,2) NOT NULL DEFAULT '0.00',
  `estimated_delivery_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '30-60 minutes',
  `max_delivery_time_minutes` int DEFAULT NULL COMMENT 'Max delivery time in minutes for SLA tracking',
  `surge_multiplier` decimal(4,2) NOT NULL DEFAULT '1.00' COMMENT 'Dynamic pricing multiplier for peak hours',
  `max_concurrent_orders` int DEFAULT NULL COMMENT 'Max orders zone can handle simultaneously',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_city` (`city`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_center_coords` (`center_lat`,`center_lng`),
