INSERT INTO `notification_templates` VALUES (1,'order_placed','order','high','✅ Order Placed Successfully','✅ تم تقديم الطلب بنجاح','Your order #{order_number} has been placed. We\'ll confirm it shortly.','تم تقديم طلبك رقم #{order_number}. سنؤكده قريباً.','✅','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"total\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(2,'order_confirmed','order','high','? Order Confirmed','? تم تأكيد الطلب','Great news! Your order #{order_number} has been confirmed.','أخبار رائعة! تم تأكيد طلبك رقم #{order_number}.','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(3,'order_preparing','order','medium','?‍? Preparing Your Order','?‍? جاري تحضير طلبك','Your order #{order_number} is being prepared with care.','جاري تحضير طلبك رقم #{order_number} بعناية.','?‍?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(4,'order_cancelled_store','order','critical','❌ Order Cancelled','❌ تم إلغاء الطلب','Unfortunately, your order #{order_number} has been cancelled. Reason: {reason}','للأسف، تم إلغاء طلبك رقم #{order_number}. السبب: {reason}','❌','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"reason\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(5,'order_modified','order','high','? Order Modified','? تم تعديل الطلب','Your order #{order_number} has been modified. New total: {total} EGP','تم تعديل طلبك رقم #{order_number}. الإجمالي الجديد: {total} جنيه','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"total\", \"changes\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(6,'payment_failed','order','critical','? Payment Failed','? فشل الدفع','Payment for order #{order_number} failed. Please try again.','فشل دفع الطلب رقم #{order_number}. يرجى المحاولة مرة أخرى.','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(7,'payment_successful','order','high','? Payment Successful','? تم الدفع بنجاح','Payment of {amount} EGP for order #{order_number} was successful.','تم دفع {amount} جنيه للطلب رقم #{order_number} بنجاح.','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"amount\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(8,'out_for_delivery','order','high','? Out for Delivery','? في الطريق إليك','Your order #{order_number} is on its way! ETA: {eta}','طلبك رقم #{order_number} في الطريق! الوصول المتوقع: {eta}','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"eta\", \"driver_name\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(9,'courier_nearby','order','high','? Courier is Nearby','? المندوب قريب منك','Your delivery for order #{order_number} is almost there! {distance} away.','توصيل طلبك رقم #{order_number} على وشك الوصول! يبعد {distance}.','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"distance\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(10,'delivery_delayed','order','high','? Delivery Delayed','? تأخر التوصيل','Sorry! Your order #{order_number} is delayed. New ETA: {new_eta}','عذراً! تأخر طلبك رقم #{order_number}. الوقت الجديد: {new_eta}','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\", \"new_eta\", \"reason\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(11,'order_delivered','order','high','? Order Delivered','? تم التوصيل','Your order #{order_number} has been delivered. Enjoy! ?','تم توصيل طلبك رقم #{order_number}. بالهنا والشفا! ?','?','navigate','/orders/{order_id}',1,1,0,0,NULL,1,1,1,'[\"order_number\", \"order_id\"]','2026-02-05 04:31:51','2026-02-05 04:31:51'),(12,'delivery_failed','order','critical','❌ Delivery Failed','❌ فشل التوصيل','We couldn\'t deliver order #{order_nu