--
-- Table structure for table `order_refunds`
--

DROP TABLE IF EXISTS `order_refunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_refunds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `paymob_payment_id` bigint unsigned DEFAULT NULL,
  `type` enum('full','partial','penalty') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'full',
  `original_amount` decimal(10,2) NOT NULL,
  `penalty_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `penalty_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `refund_amount` decimal(10,2) NOT NULL,
  `paymob_transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paymob_refund_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refund_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'paymob',
  `status` enum('pending','processing','completed','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `reason` text COLLATE utf8mb4_unicode_ci,
  `failure_reason` text COLLATE utf8mb4_unicode_ci,
  `initiated_by` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'customer',
  `admin_id` bigint unsigned DEFAULT NULL,
  `paymob_response` json DEFAULT NULL,
  `refunded_items` json DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
