  `driver_id` bigint unsigned DEFAULT NULL,
  `driver_assigned_at` timestamp NULL DEFAULT NULL,
  `driver_picked_up_at` timestamp NULL DEFAULT NULL,
  `actual_delivered_at` timestamp NULL DEFAULT NULL,
