--
-- Table structure for table `paymob_payments`
--

DROP TABLE IF EXISTS `paymob_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paymob_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `internal_order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Our internal order reference',
  `special_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Unique reference sent to Paymob for webhook correlation',
  `paymob_order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Paymob order ID from API',
  `paymob_intention_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paymob_transaction_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'From callback',
  `amount_cents` int NOT NULL COMMENT 'Amount in cents (EGP × 100)',
  `currency` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EGP',
  `payment_method` enum('CARD','WALLET') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CARD or WALLET',
  `flow` enum('classic_iframe','unified_3ds','moto') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'classic_iframe',
  `moto_attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `moto_attempted_at` timestamp NULL DEFAULT NULL,
  `is_fallback_from_moto` tinyint(1) NOT NULL DEFAULT '0',
  `save_card_requested` tinyint(1) DEFAULT '0',
  `integration_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Paymob integration ID used',
  `status` enum('PENDING','PAID','FAILED','REFUNDED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `billing_data` json NOT NULL COMMENT 'Customer billing information',
  `paymob_response` json DEFAULT NULL COMMENT 'Full Paymob callback data',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `paid_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `paymob_payments_internal_order_id_unique` (`internal_order_id`),
  UNIQUE KEY `paymob_payments_paymob_transaction_id_unique` (`paymob_transaction_id`),
  KEY `paymob_payments_internal_order_id_index` (`internal_order_id`),
  KEY `paymob_payments_paymob_order_id_index` (`paymob_order_id`),
  KEY `paymob_payments_status_index` (`status`),
  KEY `paymob_payments_created_at_index` (`created_at`),
  KEY `paymob_payments_paymob_intention_id_index` (`paymob_intention_id`),
  KEY `paymob_payments_flow_index` (`flow`),
  KEY `paymob_payments_order_id_status_created_at_index` (`order_id`,`status`,`created_at`),
  KEY `pp_user_id_idx` (`user_id`),
  KEY `pp_special_ref_idx` (`special_reference`),
  CONSTRAINT `paymob_payments_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

