DROP TABLE IF EXISTS `product_watchlist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_watchlist` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL COMMENT 'References products.barcode',
  `notify_back_in_stock` tinyint(1) NOT NULL DEFAULT '1',
  `notify_price_drop` tinyint(1) NOT NULL DEFAULT '1',
  `price_threshold` decimal(10,2) DEFAULT NULL,
  `last_known_price` decimal(10,2) DEFAULT NULL,
  `notified_back_in_stock` tinyint(1) NOT NULL DEFAULT '0',
  `notified_price_drop` tinyint(1) NOT NULL DEFAULT '0',
  `last_notified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_watchlist_user_id_product_id_unique` (`user_id`,`product_id`),
  KEY `product_watchlist_notify_back_in_stock_index` (`notify_back_in_stock`),
  KEY `product_watchlist_notify_price_drop_index` (`notify_price_drop`),
  CONSTRAINT `product_watchlist_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
