DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `barcode` bigint unsigned NOT NULL,
  `name_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `description_ar` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `packaging` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `sale_price` decimal(10,2) DEFAULT NULL,
  `active_promotion_id` bigint unsigned DEFAULT NULL,
  `cost_price` decimal(10,2) DEFAULT NULL,
  `stock_quantity` int DEFAULT '0',
  `is_in_stock` tinyint(1) NOT NULL DEFAULT '1',
  `weight` decimal(8,2) DEFAULT NULL COMMENT 'Weight in grams',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'piece' COMMENT 'piece, kg, liter, etc',
  `nutrition_facts` json DEFAULT NULL COMMENT 'Nutritional information',
  `is_featured` tinyint(1) DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `rating` decimal(3,2) NOT NULL DEFAULT '0.00',
  `review_count` int unsigned NOT NULL DEFAULT '0',
  `sales_count` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`barcode`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_slug` (`slug`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_is_featured` (`is_featured`),
  KEY `idx_price` (`price`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_stock_quantity` (`stock_quantity`),
  KEY `products_active_promotion_id_foreign` (`active_promotion_id`),
  KEY `products_is_active_index` (`is_active`),
  KEY `products_is_featured_index` (`is_featured`),
  KEY `products_is_in_stock_index` (`is_in_stock`),
  KEY `products_sales_count_index` (`sales_count`),
  KEY `products_active_stock_index` (`is_active`,`is_in_stock`),
  KEY `idx_products_featured` (`is_featured`,`is_active`),
  KEY `idx_products_price` (`price`),
  KEY `idx_products_active` (`is_active`),
  KEY `idx_products_sales` (`sales_count` DESC),
  KEY `idx_products_rating` (`rating` DESC),
  KEY `idx_products_stock` (`stock_quantity`),
  KEY `idx_products_active_featured` (`is_active`,`is_featured`),
  KEY `idx_products_active_sale` (`is_active`,`sale_price`),
  KEY `idx_products_active_sales` (`is_active`,`sales_count`),
  KEY `idx_products_active_stock` (`is_active`,`stock_quantity`),
  KEY `idx_products_promo_id` (`active_promotion_id`),
  KEY `idx_products_active_featured_created` (`is_active`,`is_featured`,`created_at`),
  KEY `idx_products_active_popularity` (`is_active`,`sales_count`),
  FULLTEXT KEY `idx_fulltext_search` (`name_en`,`name_ar`,`description_en`,`description_ar`),
  FULLTEXT KEY `ft_products_name` (`name_en`,`name_ar`),
  CONSTRAINT `products_active_promotion_id_foreign` FOREIGN KEY (`active_promotion_id`) REFERENCES `promotions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
