INSERT INTO `settings` VALUES (1,'delivery_slots','json','[{\"slot\":\"9:00 AM - 12:00 PM\",\"capacity\":50,\"is_active\":true},{\"slot\":\"12:00 PM - 3:00 PM\",\"capacity\":50,\"is_active\":true},{\"slot\":\"3:00 PM - 6:00 PM\",\"capacity\":50,\"is_active\":true},{\"slot\":\"6:00 PM - 9:00 PM\",\"capacity\":50,\"is_active\":true}]','Available delivery time slots with capacity','2025-12-24 23:26:18','2025-12-24 23:26:18');
