--
-- Table structure for table `user_purchase_patterns`
--

DROP TABLE IF EXISTS `user_purchase_patterns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_purchase_patterns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL COMMENT 'References products.barcode',
  `purchase_count` int NOT NULL DEFAULT '0',
  `avg_days_between_purchases` int DEFAULT NULL,
  `last_purchased_at` timestamp NULL DEFAULT NULL,
  `next_predicted_purchase` timestamp NULL DEFAULT NULL,
  `reorder_reminder_sent` tinyint(1) NOT NULL DEFAULT '0',
  `last_reminder_sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_purchase_patterns_user_id_product_id_unique` (`user_id`,`product_id`),
  KEY `user_purchase_patterns_next_predicted_purchase_index` (`next_predicted_purchase`),
  KEY `user_purchase_patterns_reorder_reminder_sent_index` (`reorder_reminder_sent`),
  CONSTRAINT `user_purchase_patterns_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

