  `current_lng` decimal(11,8) DEFAULT NULL COMMENT 'Driver current GPS longitude',
  `location_updated_at` timestamp NULL DEFAULT NULL COMMENT 'Last GPS update timestamp',
  `is_available` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Driver online/offline toggle',
  `assigned_zone_id` bigint unsigned DEFAULT NULL,
  `vehicle_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'motorcycle, car, bicycle',
  `vehicle_plate` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_deliveries` int NOT NULL DEFAULT '0',
  `average_rating` decimal(3,2) NOT NULL DEFAULT '0.00',
  `is_verified` tinyint(1) NOT NULL DEFAULT '0',
  `two_factor_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `push_tokens` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_phone_unique` (`phone`),
