  KEY `idx_driver_location` (`current_lat`,`current_lng`),
  KEY `idx_driver_availability` (`role`,`is_available`),
  KEY `idx_driver_zone` (`assigned_zone_id`),
  CONSTRAINT `users_assigned_zone_id_foreign` FOREIGN KEY (`assigned_zone_id`) REFERENCES `delivery_zones` (`id`) ON DELETE SET NULL
